-- Update SEO keywords for the 4 sample projects
UPDATE projects SET seoKeywords = 'scenic design, All''s Well That Ends Well, Shakespeare, New Swan Theatre Festival, operatic design' WHERE slug = 'alls-well-that-ends-well';
UPDATE projects SET seoKeywords = 'scenic design, Bell Book and Candle, realistic interior, Okoboji Summer Theatre, mid-century' WHERE slug = 'bell-book-and-candle';
UPDATE projects SET seoKeywords = 'scenic design, Million Dollar Quartet, Sun Records, South Coast Repertory, 1950s Memphis' WHERE slug = 'million-dollar-quartet';
UPDATE projects SET seoKeywords = 'scenic design, Much Ado About Nothing, Shakespeare, western, New Swan Theatre' WHERE slug = 'much-ado-about-nothing';

-- Link tags for Bell, Book and Candle
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'bell-book-and-candle'
AND t.slug IN ('1950s', 'mid-century-modern', 'realistic-interior', 'summer-stock', '2025')
ON DUPLICATE KEY UPDATE projectId=VALUES(projectId);

-- Link tags for Million Dollar Quartet
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'million-dollar-quartet'
AND t.slug IN ('1950s', 'recording-studio', 'rock-and-roll', 'regional-theatre', 'co-design', '2025')
ON DUPLICATE KEY UPDATE projectId=VALUES(projectId);

-- Link tags for Much Ado About Nothing
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'much-ado-about-nothing'
AND t.slug IN ('shakespeare', 'wild-west', 'spaghetti-western', 'saloon-design', 'theatre-festival', '2025')
ON DUPLICATE KEY UPDATE projectId=VALUES(projectId);

